function topK(nums, k) {
  // Gợi ý: min-heap kích thước k
  // - nếu heap.length < k: push + bubble up
  // - else nếu x > heap[0]: thay thế phần tử nhỏ nhất
  const heap = [];

  // helper: min-heap
  function heapInsert(v) {
    heap.push(v);
    let i = heap.length - 1;
    while (i > 0) {
      const p = Math.floor((i - 1) / 2);
      if (heap[p] <= heap[i]) break;
      [heap[p], heap[i]] = [heap[i], heap[p]];
      i = p;
    }
  }
  function heapExtract() {
    const min = heap[0];
    const last = heap.pop();
    if (heap.length > 0) {
      heap[0] = last;
      let i = 0;
      while (true) {
        const l = 2*i+1, r = 2*i+2;
        let s = i;
        if (l < heap.length && heap[l] < heap[s]) s = l;
        if (r < heap.length && heap[r] < heap[s]) s = r;
        if (s === i) break;
        [heap[i], heap[s]] = [heap[s], heap[i]];
        i = s;
      }
    }
    return min;
  }

  // TODO: duyệt nums, dùng heapInsert/heapExtract để giữ k phần tử lớn nhất
  return heap.sort((x, y) => x - y);
}
